24	function updateError(stage: 'import' | 'dispose' | 'apply' | 'rollback', options: EntryOptions, cause: unknown) {
25	  const detail = cause instanceof Error ? cause.message : String(cause)
26	  return new Error(`failed to ${stage} loader entry ${options.id} (${options.name}): ${detail}`, { cause })
