29	function takeEntries(object: {}, keys: string[]) {
30	  const result: [string, any][] = []
31	  for (const key of keys) {
32	    if (!(key in object)) continue
33	    result.push([key, object[key]])
34	    delete object[key]
35	  }
36	  return result
37	}
