39	function sortKeys<T extends {}>(object: T, prepend = ['id', 'name'], append = ['config']): T {
40	  const part1 = takeEntries(object, prepend)
41	  const part2 = takeEntries(object, append)
42	  const rest = takeEntries(object, Object.keys(object)).sort(([a], [b]) => a.localeCompare(b))
43	  return Object.assign(object, Object.fromEntries([...part1, ...rest, ...part2]))
44	}
