35	  /** Return pending import and lifecycle tasks owned by this tree. */
36	  getTasks() {
37	    return [...this.entries()]
38	      .map(entry => entry._initTask || entry.fiber?.inertia)
39	      .filter(isNonNullable)
40	  }
41	
42	  /**
43	   * Wait until this tree has no active import or lifecycle tasks.
44	   * @throws a settled fiber failure, or an aggregate when several fibers failed.
45	   */
46	  async await() {
47	    while (true) {
48	      const tasks = this.getTasks()
49	      if (tasks.length) {
50	        await Promise.allSettled(tasks)
51	        continue
52	      }
53	      const outcomes = await Promise.allSettled(
54	        [...this.entries()].map(entry => entry._await()),
55	      )
56	      const failures = outcomes
57	        .filter((outcome): outcome is PromiseRejectedResult => outcome.status === 'rejected')
58	        .map(outcome => outcome.reason)
59	      if (failures.length === 1) throw failures[0]
60	      if (failures.length > 1) throw new AggregateError(failures, 'loader fibers failed')
61	      this.ctx.reflect.notify(['loader'])
62	      if (!this.getTasks().length) return
63	    }
64	  }
