66	  ensureId(options: Partial<EntryOptions>) {
67	    if (!options.id) {
68	      do {
69	        options.id = Math.random().toString(16).slice(2, 10)
70	      } while (this.store[options.id])
71	    }
72	    return options.id!
73	  }
