/**
 * Keyless adapter that plays an agent writing and mounting its own package: one
 * `cordis_define` call, one `cordis_run` call over the identity that define
 * returned, then a report. The package it writes is the synthesized code the
 * composition manifest has to name.
 */

import type { Context } from '@deepseek-ai/cordis'
import {
  CallId,
  LlmAdapter,
  type ContentBlock,
  type GenerateOptions,
  type LlmResolvedModelInfo,
  type StreamChunk,
} from '@deepseek-ai/dsh-llm'

/** The Host half this agent writes: a plain function body returning a Cordis Plugin. */
const HOST_CODE = `
  return {
    name: 'quarantine-probe',
    apply(ctx) {
      ctx.provide('quarantineProbe', { ok: true })
    },
  }
`

/** The define receipt's rendered line, which is where the ids reach the model. */
const DEFINED = /Defined (\S+)\/(\S+) \(/

class QuarantineMockAdapter extends LlmAdapter {
  override resolveModel(provider: string, model: string): Promise<LlmResolvedModelInfo> {
    return Promise.resolve({ provider, id: model, name: model })
  }

  async * stream(options: GenerateOptions): AsyncIterable<StreamChunk> {
    const results = options.messages.flatMap(message => message.content.filter(block => block.type === 'tool-result'))
    const defined = DEFINED.exec(resultText(results))
    if (defined === null) {
      yield * call('define-call', 'cordis_define', {
        plugin: { kind: 'new', idPrefix: 'quar' },
        name: 'quarantine-probe',
        purpose: 'Prove that a session can mount code it wrote itself.',
        code: { host: HOST_CODE },
      })
      return
    }
    if (results.length === 1) {
      yield * call('run-call', 'cordis_run', {
        pluginId: defined[1],
        packageId: defined[2],
        mode: 'run',
      })
      return
    }
    yield * reply('mounted')
  }
}

/** Every text fragment of the tool results seen so far, in order. */
function resultText(results: readonly ContentBlock[]): string {
  return results
    .flatMap(block => block.type === 'tool-result' ? block.content : [])
    .flatMap(block => block.type === 'text' ? [block.text] : [])
    .join('\n')
}

/** One tool call as the canonical block sequence of a dispatching step. */
function * call(id: string, name: string, args: unknown): Generator<StreamChunk> {
  const callId = CallId(id)
  const encoded = JSON.stringify(args)
  yield { type: 'block-start', index: 0, blockType: 'tool-call' }
  yield { type: 'tool-call-delta', index: 0, id: callId, name, argumentsDelta: encoded }
  yield { type: 'block-end', index: 0, block: { type: 'tool-call', id: callId, name, arguments: encoded } }
  yield { type: 'usage', usage: { inputTokens: 11, outputTokens: 6 } }
  yield { type: 'finish', reason: { kind: 'tool-calls' } }
}

/** One text answer as the canonical block sequence of a stopped step. */
function * reply(text: string): Generator<StreamChunk> {
  yield { type: 'block-start', index: 0, blockType: 'text' }
  yield { type: 'text-delta', index: 0, text }
  yield { type: 'block-end', index: 0, block: { type: 'text', text } }
  yield { type: 'usage', usage: { inputTokens: 15, outputTokens: 2 } }
  yield { type: 'finish', reason: { kind: 'stop' } }
}

export const name = 'quarantine-mock-llm'
export const inject = ['llm']

/**
 * Register the keyless `quarantine-mock` adapter.
 * @param ctx - plugin context carrying the LLM runtime.
 */
export function apply(ctx: Context): void {
  ctx.llm.registerAdapter(['quarantine-mock'], new QuarantineMockAdapter())
}

#!/usr/bin/env node
/**
 * Test driver: boot the quarantine composition and run one turn in which the
 * agent defines and mounts a package of its own, so the persisted log carries a
 * manifest naming synthesized code beside the curated rows.
 */

import { boot, resolveConfigPath } from '@deepseek-ai/dsh-app-boot'
import type {} from '@deepseek-ai/cordis-plugin-loader'
import { runFixtureTurn } from '@deepseek-ai/dsh-loader-smoke'
import { SessionId } from '@deepseek-ai/dsh-session'

const configPath = process.argv[2]
if (configPath === undefined) throw new Error('composition-quarantine driver requires a config path')

const ctx = await boot('composition-quarantine-e2e', resolveConfigPath(configPath, undefined))
try {
  // Loader siblings mount concurrently; the driver drives the settled application.
  await ctx.get('loader')?.await()
  const created = await ctx.agents.create({
    sessionId: SessionId('composition-quarantine'),
    meta: { cwd: process.cwd() },
    agentOptions: { provider: 'quarantine-mock', model: 'quarantine-mock' },
  })
  try {
    await runFixtureTurn(ctx, { task: 'mount a package that provides quarantineProbe' })
    process.stdout.write(`${JSON.stringify({ type: 'result', sessionId: created.agent.session.id })}\n`)
  } finally {
    await created.dispose()
  }
} finally {
  await ctx.fiber.dispose()
}

import { readFile, readdir } from 'node:fs/promises'
import { join } from 'node:path'
import { fileURLToPath } from 'node:url'
import { describe, expect, it } from 'vitest'
import { ComponentId } from '@deepseek-ai/dsh-components'
import type { CompositionManifest } from '@deepseek-ai/dsh-components-manifest'
import { LOADER_SMOKE_TEST_TIMEOUT_MS, runLoaderSmoke } from '@deepseek-ai/dsh-loader-smoke'
import type { SessionEvent } from '@deepseek-ai/dsh-session'

const fixture = new URL('../../../../examples/headless-agent/tests/fixtures/composition-quarantine/', import.meta.url)
const binScript = fileURLToPath(new URL('driver.ts', fixture))
const configPath = fileURLToPath(new URL('cordis.yml', fixture))
const repoTsconfig = fileURLToPath(new URL('../../../../tsconfig.json', import.meta.url))

async function jsonlFiles(dir: string): Promise<string[]> {
  const entries = await readdir(dir, { withFileTypes: true })
  const paths = await Promise.all(entries.map(async (entry) => {
    const path = join(dir, entry.name)
    if (entry.isDirectory()) return jsonlFiles(path)
    return entry.isFile() && entry.name.endsWith('.jsonl') ? [path] : []
  }))
  return paths.flat()
}

describe('a session that mounts its own package through a real cordis.yml and headless process', () => {
  it('marks the synthesized package in the manifest beside the curated rows', async () => {
    let events: SessionEvent[] = []
    const { stderr } = await runLoaderSmoke({
      label: 'composition-quarantine',
      tempDirPrefix: 'composition-quarantine-e2e-',
      binScript,
      libBinScript: binScript,
      configPath,
      binArgs: [configPath],
      tsconfigPath: repoTsconfig,
      inspect: async (cwd) => {
        const logs = await jsonlFiles(join(cwd, '.sessions'))
        expect(logs).toHaveLength(1)
        const lines = (await readFile(logs[0] as string, 'utf8')).trimEnd().split('\n')
        events = lines.slice(1).map(line => JSON.parse(line) as SessionEvent)
      },
    })
    expect(stderr).toBe('')

    const manifests = events
      .filter(event => event.type === 'composition/manifest')
      .map(event => event.data as CompositionManifest)
    // The curated composition, then the same composition with the package the
    // agent wrote for itself mounted into it.
    expect(manifests).toHaveLength(2)
    const [curated, mounted] = manifests
    if (curated === undefined || mounted === undefined) throw new Error('expected two composition manifests')

    // Every row of the configuration is a curated plugin addressed by its
    // registration, and nothing in that composition is synthesized.
    expect(curated.components.map(entry => entry.id)).toContain(ComponentId('plugin:tool-cordis'))
    expect(curated.components.every(entry => entry.kind === 'plugin')).toBe(true)
    expect(curated.components.every(entry => entry.provenance === 'curated')).toBe(true)
    expect(curated.components.every(entry => entry.digestBasis === 'registration')).toBe(true)
    expect(curated.components.every(entry => entry.layer === 'global')).toBe(true)

    // The mount adds exactly one entry, and it is the one a quarantine keys on.
    const added = mounted.components.filter(
      entry => !curated.components.some(before => before.id === entry.id),
    )
    expect(added).toHaveLength(1)
    expect(added[0]).toMatchObject({
      kind: 'dynamic-package',
      provenance: 'synthesized',
      digestBasis: 'content',
      // Synthesized code is named in the session that wrote it, never globally.
      layer: 'agent',
    })
    expect(added[0]?.id).toMatch(/^dynamic-package:quar/)
    expect(added[0]?.digest).toMatch(/^[0-9a-f]{64}$/)
    expect(mounted.compositionSha256).not.toBe(curated.compositionSha256)

    // The mount is recorded before the step whose model request it can reach.
    const mountedSeq = events.find(
      event => event.type === 'composition/manifest' && event.data.compositionSha256 === mounted.compositionSha256,
    )?.seq
    const lastHeader = events.filter(event => event.type === 'request/header').at(-1)?.seq
    expect(mountedSeq).toBeLessThan(lastHeader ?? Number.POSITIVE_INFINITY)
  }, LOADER_SMOKE_TEST_TIMEOUT_MS)
})

